class Instrument {
  constructor(brand) {
    this.brand = brand;
  }

  play() {
    return this.brand + " instrument is playing a generic sound.";
  }
}

class Guitar extends Instrument {
  constructor(brand, type) {
    super(brand);
    this.type = type;
  }

  play() {
    return "strumming a " + this.type + " guitar";
  }
}

class Drums extends Instrument {
  constructor(brand, pieces) {
    super(brand);
    this.pieces = pieces;
  }

  play() {
    return "beating the " + this.pieces + "-piece drums";
  }
}

// --- Test cases (do not modify) ---
const guitar = new Guitar("Fender", "electric");
const drums = new Drums("Pearl", 5);

console.log(guitar.play());
console.log(drums.play());
console.log(guitar.brand);
console.log(drums.brand);

